SELECT CAST(COALESCE(SUM(CASE WHEN s.teacher_id = #{teacherId} THEN 1 ELSE 0 END), 0) AS SIGNED INTEGER) AS teacherDaily, CAST(COALESCE(SUM(CASE WHEN s.class_id = #{classId} THEN 1 ELSE 0 END), 0) AS SIGNED INTEGER) AS classDaily, CAST(COALESCE(SUM(CASE WHEN s.class_id = #{classId} AND s.course_id = #{courseId} THEN 1 ELSE 0 END), 0) AS SIGNED INTEGER) AS sameCourse FROM schedule s WHERE s.deleted = 0 AND s.time_slot_id IN
#{id}
AND s.semester_id = #{semesterId}
AND s.id <> #{excludeScheduleId}
AND s.plan_id = #{planId}
AND s.plan_id IS NULL
AND (s.week_type = 'ALL' OR s.week_type = 'ODD')
AND (s.week_type = 'ALL' OR s.week_type = 'EVEN')
